          SetGpuReg(REG_OFFSET_DISPCNT, DISPCNT_MODE_1
                                      | DISPCNT_OBJ_1D_MAP
                                      | DISPCNT_BG0_ON
                                      | DISPCNT_BG1_ON
                                      | DISPCNT_BG2_ON
                                      | DISPCNT_OBJ_ON);
          CreatePressStartBanner(START_BANNER_X, 108);
          CreateCopyrightBanner(START_BANNER_X, 148);
          gTasks[taskId].tBg1Y = 0;
          gTasks[taskId].func = Task_TitleScreenPhase3;
