/** static void UpdateLegendaryMarkingColor(u8 frameNum) */
export function UpdateLegendaryMarkingColor(frameNum: any): any {
  if ((frameNum % 4) == 0)  
      {
          let intensity: any = Cos(frameNum, Q_8_8(0.5)) + Q_8_8(0.5);
          let r: any = 31 - Q_8_8_TO_INT(intensity * 31);
          let g: any = 31 - Q_8_8_TO_INT(intensity * 22);
          let b: any = 12;

          let color: any = RGB(r, g, b);
          LoadPalette(color, BG_PLTT_ID(14) + 15, 0);
     }
}

